<div class="container-fluid"><div class="card mb-4"><div class="card-body d-flex justify-content-between"><h3 class="mb-0 bc-title"><b>{{ $deal ? __('Edit Deal') : __('Create Deal') }}</b></h3><a class="btn btn-primary btn-sm" href="{{ route('seller.deal.index') }}">{{ __('Back to Deals') }}</a></div></div><div class="card shadow"><div class="card-body">@include('alerts.alerts')<form method="post" action="{{ $deal ? route('seller.deal.update', $deal->id) : route('seller.deal.store') }}">@csrf @if($deal) @method('PUT') @endif<div class="row"><div class="col-lg-7"><div class="form-group"><label>{{ __('Deal Name') }} *</label><input class="form-control" name="name" required value="{{ old('name', optional($deal)->name) }}"></div><div class="form-group"><label>{{ __('Deal Description') }}</label><textarea class="form-control" name="description" rows="3">{{ old('description', optional($deal)->description) }}</textarea></div><div class="form-group"><label><strong>{{ __('Select Products From Your Store') }} *</strong></label><div class="border rounded p-2" style="max-height:420px;overflow:auto">@forelse($items as $item)@php($price = $item->discount_price > 0 ? $item->discount_price : $item->previous_price) <label class="d-flex align-items-center border-bottom py-2 mb-0"><input class="deal-product-checkbox mr-2" type="checkbox" name="item_ids[]" value="{{ $item->id }}" data-price="{{ $price }}" {{ in_array($item->id, old('item_ids', $selectedItemIds ?? [])) ? 'checked' : '' }}><span class="flex-grow-1">{{ $item->name }} <small class="text-muted">({{ PriceHelper::setCurrencyPrice($price) }})</small></span></label>@empty <p class="text-muted mb-0">{{ __('No eligible products available.') }}</p>@endforelse</div></div></div><div class="col-lg-5"><div class="form-group"><label>{{ __('Discount Type') }} *</label><select class="form-control" id="discount_type" name="discount_type"><option value="percent" {{ old('discount_type', optional($deal)->discount_type) !== 'fixed' ? 'selected' : '' }}>{{ __('Percentage (%)') }}</option><option value="fixed" {{ old('discount_type', optional($deal)->discount_type) === 'fixed' ? 'selected' : '' }}>{{ __('Fixed Amount Off') }}</option></select></div><div class="form-group"><label>{{ __('Discount Value') }} *</label><input class="form-control" type="number" min="0.01" step="0.01" id="discount_value" name="discount_value" required value="{{ old('discount_value', optional($deal)->discount_value ?: 10) }}"></div><div class="form-group"><label>{{ __('Deal End Date & Time') }} * <span class="badge badge-info">{{ __('Within 20 Days') }}</span></label><input class="form-control" type="datetime-local" name="end_date" required value="{{ old('end_date', optional(optional($deal)->end_date)->format('Y-m-d\\TH:i')) }}"></div><div class="alert alert-light border"><div>{{ __('Selected total:') }} <strong id="deal-total">PKR 0.00</strong></div><div>{{ __('Final deal price:') }} <strong class="text-success" id="deal-final">PKR 0.00</strong></div></div><button class="btn btn-success btn-block btn-lg"><i class="fas fa-bolt"></i> {{ $deal ? __('Apply Deal') : __('Launch Deal') }}</button></div></div></form></div></div></div>
