@section('scripts')<script>var dealCurrencyValue={{ json_encode(PriceHelper::setCurrencyValue()) }},dealCurrencySign=@json(PriceHelper::setCurrencySign());function dealMoney(v){return dealCurrencySign+' '+(v*dealCurrencyValue).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}function updateDealTotal(){var t=0;document.querySelectorAll('.deal-product-checkbox:checked').forEach(function(e){t+=parseFloat(e.dataset.price)||0});var d=parseFloat(document.getElementById('discount_value').value)||0;var f=document.getElementById('discount_type').value==='percent'?t-(t*d/100):t-(d/dealCurrencyValue);document.getElementById('deal-total').textContent=dealMoney(t);document.getElementById('deal-final').textContent=dealMoney(Math.max(0,f))}document.querySelectorAll('.deal-product-checkbox,#discount_type,#discount_value').forEach(function(e){e.addEventListener('change',updateDealTotal);e.addEventListener('input',updateDealTotal)});updateDealTotal();</script>@endsection
